import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"疾世","description":"","frontmatter":{"title":"疾世","date":"2026-11-24T00:00:00.000Z","seq":59,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王逸","source_book":"楚辞","prev":{"text":"怨上","link":"/blogs/楚辞/怨上.html"},"next":{"text":"悯上","link":"/blogs/楚辞/悯上.html"}},"headers":[],"relativePath":"blogs/楚辞/疾世.md","filePath":"blogs/楚辞/疾世.md"}'),o={name:"blogs/楚辞/疾世.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="疾世" tabindex="-1">疾世 <a class="header-anchor" href="#疾世" aria-label="Permalink to &quot;疾世&quot;">​</a></h1><p class="poem-meta">先秦 · 王逸　·　九思</p><div class="poem"><p class="poem-stanza">周徘徊兮汉渚，求水神兮灵女。</p><p class="poem-stanza">嗟此国兮无良，媒女诎兮謰謱。</p><p class="poem-stanza">鴳雀列兮譁讙，鸲鹆鸣兮聒余。</p><p class="poem-stanza">抱昭华兮宝璋，欲衒鬻兮莫取。</p><p class="poem-stanza">言旋迈兮北徂，叫我友兮配耦。</p><p class="poem-stanza">日阴曀兮未光，阒睄窕兮靡睹。</p><p class="poem-stanza">纷载驱兮高驰，将谘询兮皇羲。</p><p class="poem-stanza">遵河皋兮周流，路变易兮时乖。</p><p class="poem-stanza">濿沧海兮东游，沐盥浴兮天池。</p><p class="poem-stanza">访太昊兮道要，云靡贵兮仁义。</p><p class="poem-stanza">志欣乐兮反征，就周文兮邠歧。</p><p class="poem-stanza">秉玉英兮结誓，日欲暮兮心悲。</p><p class="poem-stanza">惟天禄兮不再，背我信兮自违。</p><p class="poem-stanza">逾陇堆兮渡漠，过桂车兮合黎。</p><p class="poem-stanza">赴昆山兮馽騄，从邛遨兮栖迟。</p><p class="poem-stanza">吮玉液兮止渴，齧芝华兮疗饥。</p><p class="poem-stanza">居嵺廓兮尠畴，远梁昌兮几迷。</p><p class="poem-stanza">望江汉兮濩渃，心紧絭兮伤怀。</p><p class="poem-stanza">时昢昢兮且旦，尘莫莫兮未晞。</p><p class="poem-stanza">忧不暇兮寝食，吒增叹兮如雷。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
